const items = $input.all();
const result = [];

for (const item of items) {
  let pdfKey = null;
  for (const key of Object.keys(item.binary ?? {})) {
    if (item.binary[key].mimeType === 'application/pdf') {
      pdfKey = key;
      break;
    }
  }

  if (!pdfKey) continue;

  result.push({ json: item.json, binary: { attachment_0: item.binary[pdfKey] } });
}

return result;

const items = $input.all();
const frenchMonthNames = ['Janvier','Février','Mars','Avril','Mai','Juin','Juillet','Août','Septembre','Octobre','Novembre','Décembre'];
const yearGroups = {};

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const text = item.json.text ?? '';
  const attachmentFileName = item.binary?.attachment_0?.fileName ?? '';

  let month = null;
  let year = null;

  // 1. PDF text: "Salaire versé le : DD/MM/YY"
  const salMatch = text.match(/Salaire vers[eé] le\s*:\s*(\d{2})\/(\d{2})\/(\d{2,4})/i);
  if (salMatch) {
    const monthNum = parseInt(salMatch[2]);
    month = frenchMonthNames[monthNum - 1] ?? null;
    const yr = salMatch[3];
    year = yr.length === 2 ? '20' + yr : yr;
  }

  // 2. Filename: _MMYYYY pattern (e.g. _092025)
  if (!month || !year) {
    const fnMatch = attachmentFileName.match(/_(\d{2})(\d{4})\.pdf$/i);
    if (fnMatch) {
      const monthNum = parseInt(fnMatch[1]);
      if (monthNum >= 1 && monthNum <= 12) {
        month = frenchMonthNames[monthNum - 1];
        year = fnMatch[2];
      }
    }
  }

  year = year || 'unknown';
  const fileName = month ? `${month}_${year}.pdf` : `unknown_${i}.pdf`;

  if (!yearGroups[year]) yearGroups[year] = {};

  const bin = item.binary?.attachment_0;
  if (bin) {
    const idx = Object.keys(yearGroups[year]).length;
    yearGroups[year][`pdf_${idx}`] = { ...bin, fileName };
  }
}

return Object.entries(yearGroups).map(([year, binaryData]) => ({
  json: { year },
  binary: binaryData
}));
